/**
 * Documentation generated by Claude
 * Purpose: Abstraction for reading, saving and removing campsite ratings.
 * Role / Design Pattern: Repository Pattern interface, so screens can be tested without Firestore.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

/**
 * Reads and writes campsite ratings. The real implementation is
 * [FirestoreRatingRepository]; tests use [InMemoryRatingRepository].
 *
 * Each operation invokes exactly one of its callbacks once it finishes.
 */
interface RatingRepository {

    /**
     * Loads the rating [userId] gave [campsiteId].
     *
     * @param onSuccess receives the stars, or null if the user hasn't rated it.
     */
    fun getMyRating(
        campsiteId: String,
        userId: String,
        onSuccess: (Int?) -> Unit,
        onFailure: (Exception) -> Unit,
    )

    /**
     * Saves [userId]'s rating for [campsiteId], replacing any earlier rating from
     * the same user, and updates the campsite's totals.
     *
     * Fails if [stars] is out of range, the campsite doesn't exist, or the user
     * owns the campsite.
     *
     * @param onSuccess receives the campsite's updated totals.
     */
    fun submitRating(
        campsiteId: String,
        userId: String,
        stars: Int,
        onSuccess: (RatingPolicy.Totals) -> Unit,
        onFailure: (Exception) -> Unit,
    )

    /**
     * Loads every rating of [campsiteId], with each rater's profile name.
     *
     * @param onSuccess receives the ratings, newest first.
     */
    fun getRatings(
        campsiteId: String,
        onSuccess: (List<CampsiteRating>) -> Unit,
        onFailure: (Exception) -> Unit,
    )

    /**
     * Removes [userId]'s rating of [campsiteId] and updates the campsite's totals,
     * for admins taking down ratings that violate the app policy.
     *
     * Fails if the campsite or the rating doesn't exist, or if the rating no
     * longer has [expectedStars] (the user changed it after the admin looked).
     *
     * @param expectedStars the stars the admin saw, or null to remove whatever is stored.
     * @param onSuccess receives the campsite's updated totals.
     */
    fun removeRating(
        campsiteId: String,
        userId: String,
        expectedStars: Int?,
        onSuccess: (RatingPolicy.Totals) -> Unit,
        onFailure: (Exception) -> Unit,
    )
}
